+// A refusal that leaves no trace is not an access control, and a trace carrying the request is a new leak.
+describe('what a refused chat request records', () => {
+  const lines: {level: string; category: string; message: string; fields?: Record<string, unknown>}[] = [];
+
+  beforeEach(() => {
+    lines.length = 0;
+    const capture = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
+      void lines.push({level, category, message, fields});
+    setLogger({
+      debug: capture('DEBUG'),
+      info: capture('INFO'),
+      warn: capture('WARN'),
+      error: capture('ERROR'),
+    });
+  });
+
+  afterEach(() => {
+    setLogger();
+  });
+
+  const unguarded = () => {
+    const app = express();
+    app.use(express.json());
+    app.use('/chats', createChatRoutes({} as unknown as ChatOrchestrator, {} as SessionStore));
+    return app;
+  };
+
+  it('emits exactly one warn on category http when no middleware is configured', async () => {
+    await request(unguarded()).post('/chats');
+
+    expect(lines).toEqual([
+      {
+        level: 'WARN',
+        category: 'http',
+        message: 'chat request refused',
+        fields: {reason: 'no auth middleware is configured'},
+      },
+    ]);
+  });
+
+  it('emits exactly one warn when the middleware attaches no usable user', async () => {
+    const {as} = harness();
+
+    await as({id: ''}).post('/chats');
+
+    expect(lines.filter(line => line.level === 'WARN')).toHaveLength(1);
+  });
+
+  it('records nothing derived from the request, so a refusal cannot leak what was asked for', async () => {
+    const {as} = harness();
+
+    await as(undefined).get('/chats/a-secret-looking-chat-id?token=shhh');
+
+    expect(JSON.stringify(lines)).not.toContain('a-secret-looking-chat-id');
+  });
+
+  it('says nothing at all when the request is authorised', async () => {
+    const {as} = harness();
+
+    await as(ALICE).post('/chats');
+
+    expect(lines.filter(line => line.level === 'WARN')).toEqual([]);
+  });
+});

commit 45e8d31f00b06fec36bd557c586d024170bfbafe
Author: vvondruska <vaclav@re-cinq.com>
Date:   Fri Sep 11 16:09:35 2026 +0200

    fix(transport): enforce chat ownership against a real user

    T013. The ownership check read `if (userId && chat.userId !== userId)`,
    so a request the middleware did not identify skipped it entirely, and
    POST /chats recorded the chat against a literal 'anonymous' owner. T012
    closed the unconfigured case; this closes the configured-but-identifies-
    nobody case, which is the one a real deployment reaches.

    requireUser runs ahead of the lookup on all three routes, so an
    unidentified caller learns nothing about which ids exist. It tests the id
    by type and emptiness rather than truthiness: id is string | number, and
    0 is a legal id that every falsy check would have rejected.

    AuthenticatedRequest is exported from the types layer and the package
    root, and HttpAuthMiddleware is stated in its terms, so what a consumer's
    middleware must produce is in the type rather than in four inline casts.
    All four casts are gone - three in the route, one in its test harness.

    Co-Authored-By: Claude Opus 5 <noreply@anthropic.com>
    Claude-Session: https://claude.ai/code/session_01CyFimiuBEQXWWBktCx6gHE

