import {jest} from '@jest/globals';
import express from 'express';
import request from 'supertest';
import {createChatRoutes} from './chats.js';
import type {AuthenticatedRequest} from '../../types/auth.js';
import type {AuthenticatedUser} from '../../types/session.js';
import {setLogger} from '../../shared/logger.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {SessionStore} from '../../types/sessionStore.js';
import type {ChatSession} from '../../types/session.js';

// Pins the ownership guard, including that a rejected request stops before the route's work.

interface TestUser extends AuthenticatedUser {
  workspaceId?: string | number;
}

const ALICE: TestUser = {id: 'alice'};
const BOB: TestUser = {id: 'bob'};

const harness = () => {
  let user: TestUser | undefined;
  const processMessage = jest.fn<(...args: unknown[]) => Promise<string>>().mockResolvedValue('assistant reply');
  const orchestrator = {processMessage} as unknown as ChatOrchestrator;

  const app = express();
  app.use(express.json());
  app.use(
    '/chats',
    createChatRoutes(orchestrator, {} as SessionStore, (req, _res, next) => {
      if (user) (req as AuthenticatedRequest).user = user;
      next();
    })
  );

  // One router means one chat store, reached by different callers - the thing the guard separates.
  const as = (next: TestUser | undefined) => {
    user = next;
    return request(app);
  };

  // Throws rather than asserts: setup that failed must name itself, not surface as a 404 from the guard.
  const chatOwnedBy = async (owner: TestUser | undefined): Promise<string> => {
    const created = await as(owner).post('/chats');
    const {id} = created.body as {id?: string};

    if (created.status !== 201 || typeof id !== 'string') {
      throw new Error(`setup: POST /chats answered ${created.status} with ${JSON.stringify(created.body)}`);
    }

    return id;
  };

  return {as, chatOwnedBy, processMessage};
};

describe('chat routes ownership guard', () => {
  describe('GET /chats/:id', () => {
    it('serves the chat to the user who created it ([validated by: serves the chat to the user who created it](src/transport/routes/chats.test.ts#L59))', async () => {
      const {as, chatOwnedBy} = harness();
      const id = await chatOwnedBy(ALICE);

      const response = await as(ALICE).get(`/chats/${id}`);

      expect({status: response.status, id: (response.body as {id: string}).id}).toEqual({status: 200, id});
    });

    it('refuses a different user with 403 and no chat content ([validated by: refuses a different user with 403 and no chat content](src/transport/routes/chats.test.ts#L68))', async () => {
      const {as, chatOwnedBy} = harness();
      const id = await chatOwnedBy(ALICE);

      const response = await as(BOB).get(`/chats/${id}`);

      expect({status: response.status, body: response.body}).toEqual({status: 403, body: {error: 'Forbidden'}});
    });

    it('answers 404 for a chat that does not exist ([validated by: answers 404 for a chat that does not exist](src/transport/routes/chats.test.ts#L77))', async () => {
      const {as} = harness();

      const response = await as(ALICE).get('/chats/no-such-chat');

      expect({status: response.status, body: response.body}).toEqual({status: 404, body: {error: 'Chat not found'}});
    });

    it('answers 404 before 403, so a wrong owner cannot probe which ids exist ([validated by: answers 404 before 403, so a wrong owner cannot probe which ids exist](src/transport/routes/chats.test.ts#L85))', async () => {
      const {as, chatOwnedBy} = harness();
      await chatOwnedBy(ALICE);

      const response = await as(BOB).get('/chats/no-such-chat');

      expect({status: response.status, body: response.body}).toEqual({status: 404, body: {error: 'Chat not found'}});
    });

    it('refuses a request whose middleware attached no user, without revealing the chat ([validated by: refuses a request whose middleware attached no user, without revealing the chat](src/transport/routes/chats.test.ts#L94))', async () => {
      const {as, chatOwnedBy} = harness();
      const id = await chatOwnedBy(ALICE);

      const response = await as(undefined).get(`/chats/${id}`);

      expect({status: response.status, body: response.body}).toEqual({status: 401, body: {error: 'Unauthorized'}});
    });

    it('compares owner ids strictly, so numeric 1 and string "1" are different users ([validated by: compares owner ids strictly, so numeric 1 and string "1" are different users](src/transport/routes/chats.test.ts#L103))', async () => {
      const {as, chatOwnedBy} = harness();
      const id = await chatOwnedBy({id: 1});

      const response = await as({id: '1'}).get(`/chats/${id}`);

      expect(response.status).toBe(403);
    });
  });

  describe('POST /chats', () => {
    // The response body is the contract a client destructures; an extra key is a leak, a missing one breaks it.
    it('answers 201 with exactly an id and a createdAt ([validated by: answers 201 with exactly an id and a createdAt](src/transport/routes/chats.test.ts#L115))', async () => {
      const {as} = harness();

      const response = await as(ALICE).post('/chats');

      expect({status: response.status, keys: Object.keys(response.body as object).sort()}).toEqual({
        status: 201,
        keys: ['createdAt', 'id'],
      });
    });

    // The workspace a chat was created in has to reach the tool context, two requests later.
    it('carries the creating user workspace through to the orchestrator ([validated by: carries the creating user workspace through to the orchestrator](src/transport/routes/chats.test.ts#L127))', async () => {
      const {as, chatOwnedBy, processMessage} = harness();
      const seen: ChatSession[] = [];
      processMessage.mockImplementation(async session => (seen.push(session as ChatSession), 'reply'));
      const owner: TestUser = {id: 'alice', workspaceId: 'w-9'};
      const id = await chatOwnedBy(owner);

      await as(owner).post(`/chats/${id}/messages`).send({content: 'hi'});

      expect(seen[0]?.workspaceId).toBe('w-9');
    });
  });

  describe('POST /chats/:id/messages', () => {
    it('accepts a message from the user who created the chat ([validated by: accepts a message from the user who created the chat](src/transport/routes/chats.test.ts#L141))', async () => {
      const {as, chatOwnedBy} = harness();
      const id = await chatOwnedBy(ALICE);

      const response = await as(ALICE).post(`/chats/${id}/messages`).send({content: 'hello'});

      expect(response.status).toBe(201);
    });

    it('refuses a different user and never reaches the orchestrator ([validated by: refuses a different user and never reaches the orchestrator](src/transport/routes/chats.test.ts#L150))', async () => {
      const {as, chatOwnedBy, processMessage} = harness();
      const id = await chatOwnedBy(ALICE);

      const response = await as(BOB).post(`/chats/${id}/messages`).send({content: 'hello'});
      const {calls} = processMessage.mock;

      expect({status: response.status, body: response.body, orchestratorCalls: calls.length}).toEqual({
        status: 403,
        body: {error: 'Forbidden'},
        orchestratorCalls: 0,
      });
    });

    it('answers 404 when the chat a message names does not exist ([validated by: answers 404 when the chat a message names does not exist](src/transport/routes/chats.test.ts#L164))', async () => {
      const {as} = harness();

      const response = await as(ALICE).post('/chats/no-such-chat/messages').send({content: 'hello'});

      expect({status: response.status, body: response.body}).toEqual({status: 404, body: {error: 'Chat not found'}});
    });

    it('refuses a different user before validating the body, so 403 beats 400 ([validated by: refuses a different user before validating the body, so 403 beats 400](src/transport/routes/chats.test.ts#L172))', async () => {
      const {as, chatOwnedBy} = harness();
      const id = await chatOwnedBy(ALICE);

      const response = await as(BOB).post(`/chats/${id}/messages`).send({});

      expect(response.status).toBe(403);
    });

    // Express leaves req.body undefined when no parser claimed the type, and destructuring it threw.
    it('answers 400 when no body parser claimed the request, rather than 500 ([validated by: answers 400 when no body parser claimed the request, rather than 500](src/transport/routes/chats.test.ts#L182))', async () => {
      const {as, chatOwnedBy} = harness();
      const id = await chatOwnedBy(ALICE);

      const response = await as(ALICE).post(`/chats/${id}/messages`).type('text/plain').send('content=hi');

      expect(response.status).toBe(400);
    });

    it('does not record the rejected message in the chat ([validated by: does not record the rejected message in the chat](src/transport/routes/chats.test.ts#L191))', async () => {
      const {as, chatOwnedBy} = harness();
      const id = await chatOwnedBy(ALICE);
      await as(BOB).post(`/chats/${id}/messages`).send({content: 'intruder'});

      const response = await as(ALICE).get(`/chats/${id}`);

      expect((response.body as {messages: unknown[]}).messages).toEqual([]);
    });
  });
});

// Pins the deny-by-default: with no middleware configured there is nobody to identify, so nothing is served.
describe('chat routes with no auth middleware', () => {
  const unguarded = () => {
    const processMessage = jest.fn<(...args: unknown[]) => Promise<string>>().mockResolvedValue('assistant reply');
    const app = express();
    app.use(express.json());
    app.use('/chats', createChatRoutes({processMessage} as unknown as ChatOrchestrator, {} as SessionStore));

