    expect({status: response.status, body: response.body}).toEqual({status: 401, body: {error: 'Unauthorized'}});
  });

  it('refuses to read a chat ([validated by: refuses to read a chat](src/transport/routes/chats.test.ts#L222))', async () => {
    const {app} = unguarded();

    const response = await request(app).get('/chats/any-id');

    expect({status: response.status, body: response.body}).toEqual({status: 401, body: {error: 'Unauthorized'}});
  });

  it('refuses to post a message, and never reaches the orchestrator ([validated by: refuses to post a message, and never reaches the orchestrator](src/transport/routes/chats.test.ts#L230))', async () => {
    const {app, processMessage} = unguarded();

    const response = await request(app).post('/chats/any-id/messages').send({content: 'hello'});
    const {calls} = processMessage.mock;

    expect({status: response.status, orchestratorCalls: calls.length}).toEqual({
      status: 401,
      orchestratorCalls: 0,
    });
  });

  it('answers 401 before 404, so an unauthenticated caller cannot probe which chat ids exist ([validated by: answers 401 before 404, so an unauthenticated caller cannot probe which chat ids exist](src/transport/routes/chats.test.ts#L242))', async () => {
    const {app} = unguarded();

    const response = await request(app).get('/chats/definitely-not-a-chat');

    expect(response.status).toBe(401);
  });
});

// Pins which `user.id` values count as authenticated. Middleware is consumer-supplied, so this is a trust boundary.
describe('chat routes user identity', () => {
  // The casts are the point: a consumer's middleware is not type-checked against AuthenticatedUser.
  const malformed = (id: unknown) => ({id}) as unknown as TestUser;

  it('accepts the numeric id 0, which is falsy but legal ([validated by: accepts the numeric id 0, which is falsy but legal](src/transport/routes/chats.test.ts#L256))', async () => {
    const {as, chatOwnedBy} = harness();
    const id = await chatOwnedBy({id: 0});

    const response = await as({id: 0}).get(`/chats/${id}`);

    expect(response.status).toBe(200);
  });

  it('refuses an empty-string id ([validated by: refuses an empty-string id](src/transport/routes/chats.test.ts#L265))', async () => {
    const {as} = harness();

    const response = await as({id: ''}).post('/chats');

    expect({status: response.status, body: response.body}).toEqual({status: 401, body: {error: 'Unauthorized'}});
  });

  it('refuses a user carrying no id ([validated by: refuses a user carrying no id](src/transport/routes/chats.test.ts#L273))', async () => {
    const {as} = harness();

    const response = await as(malformed(undefined)).post('/chats');

    expect(response.status).toBe(401);
  });

  it('refuses a null id ([validated by: refuses a null id](src/transport/routes/chats.test.ts#L281))', async () => {
    const {as} = harness();

    const response = await as(malformed(null)).post('/chats');

    expect(response.status).toBe(401);
  });

  it('never records a chat for a caller it refused ([validated by: never records a chat for a caller it refused](src/transport/routes/chats.test.ts#L289))', async () => {
    const {as} = harness();
    await as({id: ''}).post('/chats');

    const response = await as({id: 'alice'}).get('/chats/any-id');

    expect(response.status).toBe(404);
  });
