import {jest} from '@jest/globals';
import request from 'supertest';
import type {RequestHandler} from 'express';
import {createApp} from './createApp.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {AuthenticatedRequest, HttpAuthMiddleware} from '../types/auth.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';

// Pins the wiring: which routes mount, what an unauthenticated caller reaches, and what the store is for.

const orchestrator = () =>
  ({
    processMessage: jest.fn<(...args: unknown[]) => Promise<string>>().mockResolvedValue('reply'),
  }) as unknown as ChatOrchestrator;

const app = (options: Parameters<typeof createApp>[0] = {}) =>
  createApp({orchestrator: orchestrator(), sessionStore: new InMemorySessionStore(), ...options});

// Throws rather than asserts: a creation that failed would otherwise satisfy the 404 its caller expects.
const createdId = (response: {status: number; body: unknown}): string => {
  const {id} = response.body as {id?: string};

  if (response.status !== 201 || typeof id !== 'string') {
    throw new Error(`setup: POST /hal/chats answered ${response.status} with ${JSON.stringify(response.body)}`);
  }

  return id;
};

describe('createApp with no auth middleware', () => {
  it('refuses to create a chat ([validated by: refuses to create a chat](src/transport/createApp.test.ts#L29))', async () => {
    const response = await request(app()).post('/hal/chats');

    expect(response.status).toBe(401);
  });

  // The deny-by-default must not take the rest of the app with it.
  it('still answers health, so a denied chat route is not a broken app ([validated by: still answers health, so a denied chat route is not a broken app](src/transport/createApp.test.ts#L36))', async () => {
    const response = await request(app()).get('/hal/health');

    expect(response.status).toBe(200);
  });

  it('still answers 404 off the base path ([validated by: still answers 404 off the base path](src/transport/createApp.test.ts#L42))', async () => {
    const response = await request(app()).get('/anything-else');

    expect(response.status).toBe(404);
  });
});

describe('createApp auth middleware', () => {
  it('invokes the middleware it was given ([validated by: invokes the middleware it was given](src/transport/createApp.test.ts#L48))', async () => {
    const middleware = jest.fn<HttpAuthMiddleware>((req, _res, next) => {
      (req as AuthenticatedRequest).user = {id: 'alice'};
      next();
    });

    await request(app({authMiddleware: middleware})).post('/hal/chats');

    expect(middleware).toHaveBeenCalledTimes(1);
  });

  it('serves the route once that middleware attaches a user ([validated by: serves the route once that middleware attaches a user](src/transport/createApp.test.ts#L59))', async () => {
    const attach: HttpAuthMiddleware = (req, _res, next) => {
      (req as AuthenticatedRequest).user = {id: 'alice'};
      next();
    };

    const response = await request(app({authMiddleware: attach})).post('/hal/chats');

    expect(response.status).toBe(201);
  });

  // A consumer's existing Express middleware has to keep type-checking against the option.
  it('accepts a plain express RequestHandler, which is what a consumer already has ([validated by: accepts a plain express RequestHandler, which is what a consumer already has](src/transport/createApp.test.ts#L71))', () => {
    const existing: RequestHandler = (_req, _res, next) => next();
    const assigned: HttpAuthMiddleware = existing;

    expect(typeof assigned).toBe('function');
  });

  it('is itself usable as an express RequestHandler, which is how the router mounts it ([validated by: is itself usable as an express RequestHandler, which is how the router mounts it](src/transport/createApp.test.ts#L78))', () => {
    const ours: HttpAuthMiddleware = (_req, _res, next) => next();
    const mounted: RequestHandler = ours;

    expect(typeof mounted).toBe('function');
  });
});

describe('createApp chat route mounting', () => {
  it('mounts no chat routes without a session store ([validated by: mounts no chat routes without a session store](src/transport/createApp.test.ts#L86))', async () => {
    const response = await request(createApp({orchestrator: orchestrator()})).post('/hal/chats');

    expect(response.status).toBe(404);
  });

  // sessionStore gates whether the routes mount; the routes themselves keep their own Map.
  it('leaves the session store empty after a chat is created through it ([validated by: leaves the session store empty after a chat is created through it](src/transport/createApp.test.ts#L93))', async () => {
    const store = new InMemorySessionStore();
    const attach: HttpAuthMiddleware = (req, _res, next) => {
      (req as AuthenticatedRequest).user = {id: 'alice'};
      next();
    };
    await request(createApp({orchestrator: orchestrator(), sessionStore: store, authMiddleware: attach})).post(
      '/hal/chats'
    );

    expect(store.count()).toBe(0);
  });

  it('does not share chats between two apps built on one session store ([validated by: does not share chats between two apps built on one session store](src/transport/createApp.test.ts#L106))', async () => {
    const store = new InMemorySessionStore();
    const attach: HttpAuthMiddleware = (req, _res, next) => {
      (req as AuthenticatedRequest).user = {id: 'alice'};
      next();
    };
    const options = {orchestrator: orchestrator(), sessionStore: store, authMiddleware: attach};
    const created = await request(createApp(options)).post('/hal/chats');
    const id = createdId(created);

    const response = await request(createApp(options)).get(`/hal/chats/${id}`);

    expect(response.status).toBe(404);
  });
});

describe('createApp rootRoutes extension', () => {
  it('mounts a rootRoutes handler at / before the catch-all 404', async () => {
    const a = createApp({
      rootRoutes: router => router.get('/', (_req, res) => res.send('<html>hi</html>')),
    });

    const root = await request(a).get('/');
    const health = await request(a).get('/hal/health');

    expect({rootStatus: root.status, healthStatus: health.status, healthOk: health.body?.status}).toEqual({
      rootStatus: 200,
      healthStatus: 200,
      healthOk: 'ok',
    });
  });

  it('lets rootRoutes at /health and the basePath health answer independently', async () => {
    const a = createApp({
      rootRoutes: router => router.get('/health', (_req, res) => res.json({source: 'root'})),
    });

    const rootHealth = await request(a).get('/health');
    const engineHealth = await request(a).get('/hal/health');

    expect({rootBody: rootHealth.body, engineStatus: engineHealth.status}).toEqual({
      rootBody: {source: 'root'},
      engineStatus: 200,
    });
  });
});

