import {WebSocket} from 'ws';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {answeringOrchestrator, stopEngines} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {AddressInfo} from 'node:net';
import type {Express} from 'express';

describe('list_sessions when history is disabled', () => {
  afterEach(stopEngines);

  it('answers UNSUPPORTED when history is not enabled ([validated by: answers UNSUPPORTED when history is not enabled](src/transport/historyDisabled.test.ts#L12))', async () => {
    const store = new InMemorySessionStore();
    const hal = createServer({
      app: (() => undefined) as unknown as Express,
      wsAuth: async () => ({id: 'u1'}),
      sessionStore: store,
      orchestrator: answeringOrchestrator,
      history: {enabled: false}, // Disabled
    });
    await hal.start(0);
    const {port} = hal.server.address() as AddressInfo;
    const url = `ws://127.0.0.1:${port}/hal/ws`;

    const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
    const frames: any[] = [];
    await new Promise<void>((resolve) => {
      client.on('message', (raw) => {
        const frame = JSON.parse(String(raw));
        if (frame.type === 'connected') {
          client.send(JSON.stringify({type: 'list_sessions'}));
          client.send(JSON.stringify({type: 'ping', timestamp: 1}));
        } else if (frame.type === 'pong') {
          resolve();
        } else {
          frames.push(frame);
        }
      });
    });

    expect(frames).toContainEqual({
      type: 'error',
      code: 'UNSUPPORTED',
      message: 'Conversation history is not enabled',
    });
  });
});
